INSERT INTO `blog` (`id`, `title`, `date`, `venue`, `story`, `top_photo`, `other_photos`, `created_at`) VALUES
(1, 'Turning Point Magazine Launch', 'November 29, 2024', 'Nairobi Safari Club', '<p><strong>Turning Point Magazine</strong>&nbsp;debuted as a platform to amplify voices that impact lives but often go unheard. Its first issue, themed around&nbsp;<strong>Mental Health Management</strong>, featured over 30 contributors offering expert insights on improving mental health care and its role in social and economic well-being. A key panel discussion highlighted the mental health challenges in Nairobi, particularly among men. The launch was attended by executives from various organizations and government ministries.</p>\r\n<p class=\"future-plans\"><strong>Future Plans</strong></p>\r\n<ul>\r\n<li><strong>CEO&rsquo;s Breakfast Meeting (January 2025):</strong>&nbsp;A high-level meeting to foster partnerships with public benefit organizations and corporations.</li>\r\n<li><strong>Cultural and Trade Fair (March 2025):</strong>&nbsp;A launch event focused on&nbsp;<strong>Women in Leadership</strong>, linked to International Women\'s Day, featuring a cultural and trade fair.</li>\r\n</ul>', 'assets/uploads/blt.webp', '[\"assets\\/uploads\\/bl1.webp\",\"assets\\/uploads\\/bl2.webp\",\"assets\\/uploads\\/bl3.webp\",\"assets\\/uploads\\/bl4.webp\",\"assets\\/uploads\\/bl5.webp\",\"assets\\/uploads\\/bl6.webp\",\"assets\\/uploads\\/bl7.webp\",\"assets\\/uploads\\/bl8.webp\",\"assets\\/uploads\\/bl9.webp\",\"assets\\/uploads\\/bl10.webp\"]', '2025-01-06 12:22:56'),
(2, 'Elite Brands Award Win', 'December 13, 2024', 'Nairobi Safari Club', '<p><strong>Turning Point Magazine</strong>&nbsp;is honored to announce that we have been recognized at the&nbsp;<strong>Elite Brands Awards International</strong>&nbsp;2024. This prestigious award celebrates industry leaders for their&nbsp;<strong>innovation, quality, and service excellence</strong>&nbsp;across 18 countries, bringing attention to organizations that positively impact their sectors while upholding best practices and ethical leadership.<br><br>The Elite Brands Awards process is rigorous, with winners selected through a combination of public voting and expert evaluation. We are proud to have received the&nbsp;<strong>Public Relations and Communications Company of the Year</strong>&nbsp;award, which was presented to us on&nbsp;<strong>December 13th, 2024</strong>, during a grand gala event.<br><br>We would like to extend our heartfelt gratitude to&nbsp;<strong>our readers, partners, and the community</strong>&nbsp;for your continued support. Your trust and encouragement have been integral to our success, and we promise to keep striving for excellence in all that we do.<br><br>Thank you for being a part of our journey. Here&rsquo;s to many more milestones ahead!</p>', 'assets/uploads/g10.jpg', '[\"assets\\/uploads\\/a.JPG\",\"assets\\/uploads\\/g.JPG\",\"assets\\/uploads\\/g1.JPG\",\"assets\\/uploads\\/g2.JPG\",\"assets\\/uploads\\/g3.JPG\",\"assets\\/uploads\\/g4.JPG\",\"assets\\/uploads\\/g5.JPG\",\"assets\\/uploads\\/g6.JPG\",\"assets\\/uploads\\/g8.JPG\",\"assets\\/uploads\\/g9.jpg\",\"assets\\/uploads\\/g10.jpg\",\"assets\\/uploads\\/g11.jpg\"]', '2025-03-13 15:07:59'),
(3, 'International Women\'s Day 2025 Celebration', 'March 7, 2025', 'Kenyatta International Convention Center(KICC)', '<p data-start=\"161\" data-end=\"658\"><strong data-start=\"161\" data-end=\"355\">Turning Point Magazine marked International Women\'s Day 2025 with a landmark two-day celebration held from March 7&ndash;8 at the Kenyatta International Convention Centre (KICC) in Nairobi, Kenya.</strong> Under the global theme <em data-start=\"379\" data-end=\"429\">&ldquo;Accelerating Action Towards Women Empowerment,&rdquo;</em> the event brought together influential leaders, advocates, and change-makers from across sectors to champion gender equality and amplify the voices of women in leadership, innovation, entrepreneurship, and community development.</p>\r\n<p data-start=\"660\" data-end=\"1242\">The event featured a dynamic program of keynote speeches, panel discussions, exhibitions, and recognition ceremonies. A powerful highlight was the keynote address by Hon. Harriette Chiggai, Cabinet Secretary and President&rsquo;s Advisor on Women&rsquo;s Rights, who emphasized the need for cross-sector collaboration, innovation, and investment in women\'s advancement. The celebration also honored the <em data-start=\"1051\" data-end=\"1083\">&ldquo;25 Influential Women of 2025&rdquo; </em>a moving tribute recognizing trailblazing women whose resilience and leadership continue to inspire transformative change in their communities and industries.</p>\r\n<p data-start=\"1244\" data-end=\"1748\">Additional highlights included interactive exhibitions showcasing women-led enterprises, the launch of the second issue of <em data-start=\"1367\" data-end=\"1391\">Turning Point Magazine</em>, and solution-focused forums that addressed digital literacy, financial inclusion, and policy reform. The event served not only as a platform for knowledge sharing and inspiration but also as a catalyst for meaningful action reinforcing the importance of collective momentum in building a more inclusive and equitable future for women and girls everywhere.</p>', 'assets/uploads/Turning Point Magazine Award Ceremony_20250307_DK5A8197.webp', '[\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A1175.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A1248.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A1302.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A1380.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A8189.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A8268.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A8316.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A8491.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A8575.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A8589.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A8718.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A8733.webp\",\"assets\\/uploads\\/Turning Point Magazine Award Ceremony_20250307_DK5A9012.webp\"]', '2025-06-19 18:56:33'),
(4, 'Turning Point Magazine at JiPosition 2.0 ', 'June 27, 2025', 'Westside Tower - Lower Kabete Road', '<p data-start=\"226\" data-end=\"778\">On June 27th, 2025, part of our Turning Point Magazine team had the amazing opportunity to attend the <strong data-start=\"328\" data-end=\"360\">Position 2.0 Career Workshop</strong> at <strong data-start=\"364\" data-end=\"398\">GOMYCODE Kenya, Westside Tower</strong>. With a strong focus on <strong data-start=\"423\" data-end=\"440\">career growth</strong>, <strong data-start=\"442\" data-end=\"462\">money management</strong>, and <strong data-start=\"468\" data-end=\"487\">mental wellness</strong>, the event pulled in university students, fresh graduates, and job seekers from all over Nairobi. Our CEO took the stage and delivered a very engaging and inspiring talk that had the audience nodding and laughing along. It was great to see such an interactive crowd eager to learn and grow.</p>\r\n<p data-start=\"780\" data-end=\"1226\">Beyond the inspiring sessions, the event was a great networking hub! Our team connected with students, young professionals, and even fellow speakers. We also got the chance to hand out our <strong data-start=\"969\" data-end=\"1002\">Turning Point Magazine flyers</strong> and spread the word about our platform. The energy in the room was just electric, and we&rsquo;re grateful to the <strong data-start=\"1111\" data-end=\"1160\">Nairobi Youth &amp; Student Leaders Forum (NYSLF)</strong> and all the partners for putting together such a fantastic event.</p>', 'assets/uploads/4X3A0321.jpg', '[\"assets\\/uploads\\/4X3A0071.jpg\",\"assets\\/uploads\\/4X3A0072.jpg\",\"assets\\/uploads\\/4X3A0148.jpg\",\"assets\\/uploads\\/4X3A0185.jpg\",\"assets\\/uploads\\/4X3A0188.jpg\",\"assets\\/uploads\\/4X3A0189.jpg\",\"assets\\/uploads\\/4X3A0190.jpg\",\"assets\\/uploads\\/4X3A0194.jpg\",\"assets\\/uploads\\/4X3A0196.jpg\",\"assets\\/uploads\\/4X3A0204.jpg\",\"assets\\/uploads\\/4X3A0233.jpg\",\"assets\\/uploads\\/4X3A0239.jpg\",\"assets\\/uploads\\/4X3A0240.jpg\",\"assets\\/uploads\\/4X3A0321.jpg\"]', '2025-06-30 10:34:42');
