INSERT INTO `categories` (`id`, `name`, `description`, `created_at`) VALUES
(2, 'Society & Culture', 'Society & Culture explores the collective human experience, delving into how traditions, communities, and shared values shape the way we live. This category celebrates diversity, progress, and the ongoing dialogue that defines humanity.', '2025-01-15 08:34:28'),
(3, 'Health & Wellness', 'A dedicated space to explore balanced living, offering tips and insights to help individuals maintain their health and vitality in an ever-changing world.', '2025-01-15 08:35:28'),
(4, 'Leadership & Development', 'Leadership examines the principles, challenges, and practices that empower individuals to guide others and create meaningful impact.', '2025-01-15 08:36:06'),
(5, 'Personal Growth & Lifestyle', 'Personal Growth & Lifestyle celebrates the art of self-discovery, balance, and living meaningfully, touching on everything from personal development to aesthetic choices.', '2025-01-15 08:36:42'),
(6, 'Education & Empowerment', 'Education & Empowerment celebrates knowledge as a transformative force, exploring how learning and grassroots efforts drive change and inspire generations.', '2025-01-15 08:38:19'),
(7, 'History', 'History & Urban Development uncovers the stories of how cities and communities have evolved, linking the past to the present and inspiring future growth.', '2025-01-15 08:38:57'),
(8, 'Art & Photography', 'Art & Photography celebrates visual storytelling and creative expression, capturing the beauty and depth of the world through diverse perspectives.', '2025-01-15 08:39:24'),
(9, 'Environment & Wildlife', 'Environment & Wildlife highlights the intricate connection between humans and nature, advocating for conservation and appreciation of the planet’s rich biodiversity.', '2025-01-15 08:39:53'),
(10, 'Non-Profit Impact', 'NGOs', '2025-01-15 08:48:46');
